import {
  handleHttpError,
  enableNotifications,
  checkInput,
} from '/static/js/common/functions.prod.js';
import { showErrorMessage } from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  (NProgress.done(),
    $(document).ajaxError(function (t, e) {
      handleHttpError(e.status);
    }),
    $(document).ajaxStart(function () {
      NProgress.start();
    }),
    $(document).ajaxComplete(function () {
      (checkInput(), NProgress.done());
    }),
    $(document).on('htmx:beforeRequest', function () {
      NProgress.start();
    }),
    $(document).on('htmx:afterSwap', function () {
      (checkInput(), NProgress.done());
    }),
    window.addEventListener('popstate', () => {
      (NProgress.start(),
        setTimeout(() => {
          NProgress.done();
        }, 1e3));
    }));
  let t = new URLSearchParams(window.location.search).get('view_page');
  (t &&
    (NProgress.start(),
    $.ajax({
      type: 'GET',
      url: `?page=${t}`,
      success: function (t) {
        ($('.mainContent').empty().append(t), NProgress.done());
      },
    })),
    document.body.addEventListener('htmx:responseError', function (t) {
      handleHttpError(t.detail.xhr.status);
    }),
    $('main').on('click', '.checkbox', async function () {
      $(this).prop('checked')
        ? await enableNotifications()
        : showErrorMessage(
            gettext('Notifications Silenced'),
            gettext('You will not receive notifications')
          );
    }),
    window.visualViewport?.addEventListener('resize', () => {
      document.documentElement.style.setProperty(
        '--vh',
        `${window.visualViewport.height}px`
      );
    }));
});
